const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/instructions',
  headers: {'content-type': 'application/json'},
  body: {
    instruction: {
      number: 1,
      title: 'Fix this thing',
      status: 'draft',
      instruction_type_id: 1,
      instruction_from_id: 1,
      date_received: '2016-10-13',
      schedule_impact: {status: 'yes_known', value: 14},
      cost_impact: {status: 'yes_known', value: 12039.55},
      private: false,
      description: 'This is a description',
      attention_ids: [0],
      distribution_member_ids: [0],
      trade_ids: [0],
      attachments: ['string'],
      upload_ids: ['1ZE146W9K804SAJJZX19JVAD0R']
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/instructions"),
    Content = new StringContent("{\"instruction\":{\"number\":1,\"title\":\"Fix this thing\",\"status\":\"draft\",\"instruction_type_id\":1,\"instruction_from_id\":1,\"date_received\":\"2016-10-13\",\"schedule_impact\":{\"status\":\"yes_known\",\"value\":14},\"cost_impact\":{\"status\":\"yes_known\",\"value\":12039.55},\"private\":false,\"description\":\"This is a description\",\"attention_ids\":[0],\"distribution_member_ids\":[0],\"trade_ids\":[0],\"attachments\":[\"string\"],\"upload_ids\":[\"1ZE146W9K804SAJJZX19JVAD0R\"]}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

